.label{font-size:12px; font-weight:900; color:rgba(255,255,255,.70); letter-spacing:.2px}
.input{
  width:100%;
  padding:14px 14px;
  border-radius:16px;
  border:1px solid rgba(255,255,255,.14);
  background:rgba(255,255,255,.06);
  color:#fff;
  font-weight:700;
  outline:none;
