.input:focus{border-color:rgba(229,9,20,.55); box-shadow:0 0 0 4px var(--focus)}

.help-toggle{
  margin-top:10px;
  padding-top:12px;
  border-top:1px solid rgba(255,255,255,.10);
}
.help-btn{
  padding:0;
  background:none;
  border:0;
  color:rgba(255,255,255,.76);
  font-weight:900;
  cursor:pointer;
  text-decoration:underline;
  text-underline-offset:3px;
}
.help-panel{
  max-height:0;
  overflow:hidden;
  transition:max-height .22s ease;
}
.help-panel-inner{padding-top:10px; color:rgba(255,255,255,.70); line-height:1.5; font-size:14px}
.help-toggle[aria-expanded="true"] .help-panel{max-height:240px}

.notice{
  margin-top:10px;
  color:rgba(255,255,255,.56);
  font-size:12px;
  line-height:1.4;
